package com.primehr.learningdevelopment.api;
import com.primehr.learningdevelopment.domain.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.*;import java.util.List;
public final class LdFoundationDtos {private LdFoundationDtos(){}
 public record DefinitionTransition(@NotNull Long recordVersion,@NotBlank @Size(max=1000)String reason){}
 public record PublishTransition(@NotNull Long recordVersion,@NotNull LocalDate effectiveFrom,LocalDate effectiveTo,@NotBlank @Size(max=1000)String reason){}
 public record RegistryTransition(@NotNull Long recordVersion,@NotBlank @Size(max=1000)String reason){}
 public record PolicyInput(@NotBlank@Size(max=80)String code,@NotBlank@Size(max=200)String title,@Size(max=2000)String description,@NotBlank@Size(max=1000)String legalBasis,@Min(1)@Max(12)int planningYearStartMonth,@Min(0)int minimumPlannedInterventions,@NotNull@DecimalMin("0")BigDecimal supervisoryMinimumHours,@Min(0)int behaviorEvaluationMinDays,@Min(0)int behaviorEvaluationMaxDays,boolean requiresIdp,boolean requiresSupervisorRecommendation,boolean requiresFinalApproval,Long recordVersion){}
 public record PolicyResponse(String id,String policyId,String code,String title,String description,String legalBasis,int planningYearStartMonth,int minimumPlannedInterventions,BigDecimal supervisoryMinimumHours,int behaviorEvaluationMinDays,int behaviorEvaluationMaxDays,boolean requiresIdp,boolean requiresSupervisorRecommendation,boolean requiresFinalApproval,int definitionVersion,String supersedesId,String status,LocalDate effectiveFrom,LocalDate effectiveTo,String publishedBy,Instant publishedAt,String retiredBy,Instant retiredAt,String retirementReason,long recordVersion){}
 public record InterventionInput(@NotBlank@Size(max=80)String code,@NotBlank@Size(max=200)String title,@Size(max=2000)String description,@NotNull LdInterventionVersion.Category category,@NotNull LdInterventionVersion.Modality defaultModality,@NotBlank@Size(max=3000)String intendedOutcomes,@Size(max=3000)String deliveryRequirements,Long recordVersion){}
 public record InterventionResponse(String id,String interventionId,String code,String title,String description,String category,String defaultModality,String intendedOutcomes,String deliveryRequirements,int definitionVersion,String supersedesId,String status,LocalDate effectiveFrom,LocalDate effectiveTo,String publishedBy,Instant publishedAt,String retiredBy,Instant retiredAt,String retirementReason,long recordVersion){}
 public record ProviderInput(@NotBlank@Size(max=80)String code,@NotBlank@Size(max=250)String name,@NotNull LdProvider.Type providerType,@Size(max=500)String accreditationReference,@Size(max=1000)String contactDetails,Long recordVersion){}
 public record ProviderResponse(String id,String code,String name,String providerType,String accreditationReference,String contactDetails,String status,long recordVersion){}
 public record ResourcePersonInput(@NotBlank@Size(max=80)String code,@NotNull LdResourcePerson.Source personSource,@Size(max=100)String employeeNo,@NotBlank@Size(max=250)String displayName,@Size(max=36)String providerId,@Size(max=2000)String expertise,@Size(max=2000)String credentials,@Size(max=1000)String contactDetails,Long recordVersion){}
 public record ResourcePersonResponse(String id,String code,String personSource,String employeeNo,String displayName,String providerId,String expertise,String credentials,String contactDetails,String status,long recordVersion){}
 public record EvaluationLevelInput(@NotNull LdEvaluationLevel.Type levelType,boolean required,@Min(0)int dueAfterDays,@NotNull LdEvaluationLevel.ScoreMethod scoreMethod,@DecimalMin("0")BigDecimal passingScore,@NotBlank@Size(max=3000)String evidenceRequirements,@NotBlank@Size(max=3000)String instrumentGuidance,@Min(1)int displayOrder){}
 public record EvaluationFrameworkInput(@NotBlank@Size(max=80)String code,@NotBlank@Size(max=200)String title,@Size(max=2000)String description,@NotBlank@Size(max=1000)String legalBasis,Long recordVersion){}
 public record EvaluationLevelsInput(@NotNull Long recordVersion,@NotEmpty List<@Valid EvaluationLevelInput> levels){}
 public record EvaluationLevelResponse(String id,String levelType,boolean required,int dueAfterDays,String scoreMethod,BigDecimal passingScore,String evidenceRequirements,String instrumentGuidance,int displayOrder){}
 public record EvaluationFrameworkResponse(String id,String frameworkId,String code,String title,String description,String legalBasis,int definitionVersion,String supersedesId,String status,int levelRevision,LocalDate effectiveFrom,LocalDate effectiveTo,String publishedBy,Instant publishedAt,String retiredBy,Instant retiredAt,String retirementReason,long recordVersion,List<EvaluationLevelResponse> levels){}
}
